"""Vetted product backlog the Muse draws from each week (works fully offline).
Each entry becomes a catalog line. Specs are validated before building."""


def P(exp=0, con=1.0, sat=1.0, temp=0.0, tint=0.0, lift=0.0, roll=0.35, **kw):
    return dict(exp=exp, contrast=con, sat=sat, temp=temp, tint=tint, lift=lift, roll=roll, **kw)


def L(name, desc, **p):
    return {"name": name, "desc": desc, "params": P(**p)}


